"""Independent yield-generator runner. Executes each yielded continuation
IMMEDIATELY after next() (matching nose semantics) so late-binding closures
over loop variables behave as they do under nose."""
import ast, os, sys, traceback, importlib

TESTS = sys.argv[1]
sys.path.insert(0, os.path.dirname(TESTS))
sys.path.insert(0, os.path.dirname(os.path.dirname(TESTS)))
os.chdir(os.path.dirname(TESTS))

MODS = ['tests.test_fields', 'tests.test_api', 'tests.test_inputs']

def expected_counts(path):
    """AST: for `for <t> in <literal>:` loops containing a yield, the literal length.
    For flat generators, count top-level yields."""
    out = {}
    tree = ast.parse(open(path).read())
    for node in tree.body:
        if not (isinstance(node, ast.FunctionDef) and node.name.startswith('test')):
            continue
        if not any(isinstance(n, (ast.Yield, ast.YieldFrom)) for n in ast.walk(node)):
            continue
        total = 0
        for stmt in ast.walk(node):
            if isinstance(stmt, ast.For) and any(
                    isinstance(n, ast.Yield) for n in ast.walk(stmt)):
                it = stmt.iter
                if isinstance(it, (ast.List, ast.Tuple, ast.Set)):
                    total += len(it.elts)
                elif isinstance(it, ast.Name):
                    # resolve simple `values = [...]` assignment in same function
                    for s2 in node.body:
                        if isinstance(s2, ast.Assign) and any(
                                isinstance(t, ast.Name) and t.id == it.id for t in s2.targets):
                            if isinstance(s2.value, (ast.List, ast.Tuple, ast.Set)):
                                total = total + len(s2.value.elts)
                else:
                    total = None
        if total == 0:  # flat: count yield statements directly in body
            total = sum(1 for n in ast.walk(node) if isinstance(n, ast.Yield))
        out[node.name] = total
    return out

results = []
for modname in MODS:
    mod = importlib.import_module(modname)
    exp = expected_counts(mod.__file__.replace('.pyc', '.py'))
    for name in sorted(dir(mod)):
        if not name.startswith('test'):
            continue
        fn = getattr(mod, name)
        if not (callable(fn) and getattr(fn, '__code__', None)
                and fn.__code__.co_flags & 0x20):  # CO_GENERATOR
            continue
        gen = fn()
        idx = 0
        passed = failed = 0
        aborted = None
        while True:
            try:
                item = next(gen)
            except StopIteration:
                break
            except Exception as e:
                aborted = "ABORT during next() at index %d: %s: %s" % (
                    idx, type(e).__name__, e)
                break
            # execute immediately
            try:
                if callable(item):
                    item()
                else:
                    f, args = item[0], item[1:]
                    f(*args)
                passed += 1
            except Exception as e:
                failed += 1
                results.append(('FAIL', modname, name, idx, item,
                                "%s: %s" % (type(e).__name__, e)))
            idx += 1
        results.append(('SUMMARY', modname, name, idx, exp.get(name), aborted,
                        passed, failed))

print("%-22s %-34s %6s %6s %5s %5s  %s" % (
    "module", "generator", "ran", "expect", "pass", "fail", "abort"))
tot = tf = 0
for r in results:
    if r[0] != 'SUMMARY':
        continue
    _, m, n, ran, expct, abort, p, f = r
    tot += ran; tf += f
    flag = "" if (expct is None or expct == ran) else "  <<< COUNT MISMATCH"
    print("%-22s %-34s %6d %6s %5d %5d  %s%s" % (
        m.split('.')[-1], n, ran, expct, p, f, abort or "-", flag))
print("\nTOTAL sub-cases run: %d, failures: %d" % (tot, tf))
print("\n--- FAILURE DETAIL ---")
for r in results:
    if r[0] == 'FAIL':
        _, m, n, idx, item, err = r
        print("%s::%s [index %d] -> %s" % (m, n, idx, err))
